-- Boss rosters: WoW Forever client data (Undying), Classic guide comparisons (Wowhead/Wowcalc).
-- No coordinates are invented. Text-only guides do not claim a map marker or a traversable path.
local A = DungeonMapPilot
A.routeVariants = {}
local function makeStep(id, kind, en, fr, bodyEN, bodyFR, floor)
  return {id=id,kind=kind,title={en=en,fr=fr},body={en=bodyEN,fr=bodyFR},floor=floor}
end
